const resumePalaceJob = `-- name: ResumePalaceJob :execrows
UPDATE palace_jobs SET status = 'queued', control_state = 'run', updated_at_ms = ?
WHERE id = ? AND status IN ('queued', 'running') AND control_state = 'paused'
`

type ResumePalaceJobParams struct {
	UpdatedAtMs int64  `json:"updated_at_ms"`
	ID          string `json:"id"`
}

func (q *Queries) ResumePalaceJob(ctx context.Context, arg ResumePalaceJobParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, resumePalaceJob, arg.UpdatedAtMs, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const saveConversation = `-- name: SaveConversation :execrows
UPDATE chat_conversations SET title=?,messages_json=?,message_count=?,
    active_turn_id=?,updated_at_ms=?,revision=revision+1 WHERE id=? AND revision=?
`

type SaveConversationParams struct {
	Title        string `json:"title"`
	MessagesJson string `json:"messages_json"`
	MessageCount int64  `json:"message_count"`
	ActiveTurnID string `json:"active_turn_id"`
	UpdatedAtMs  int64  `json:"updated_at_ms"`
	ID           string `json:"id"`
	Revision     int64  `json:"revision"`
}

func (q *Queries) SaveConversation(ctx context.Context, arg SaveConversationParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, saveConversation,
		arg.Title,
		arg.MessagesJson,
		arg.MessageCount,
		arg.ActiveTurnID,
		arg.UpdatedAtMs,
		arg.ID,
		arg.Revision,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

