const setCursor = `-- name: SetCursor :exec
INSERT INTO study_cursors (subject_id, question_id) VALUES (?, ?)
ON CONFLICT (subject_id) DO UPDATE SET question_id = excluded.question_id
`

type SetCursorParams struct {
	SubjectID  int64 `json:"subject_id"`
	QuestionID int64 `json:"question_id"`
}

func (q *Queries) SetCursor(ctx context.Context, arg SetCursorParams) error {
	_, err := q.db.ExecContext(ctx, setCursor, arg.SubjectID, arg.QuestionID)
	return err
}

