const subjectOverview = `-- name: SubjectOverview :one
SELECT COUNT(*) AS total,
    COUNT(CASE WHEN p.state = 'mastered' THEN 1 END) AS mastered,
    COUNT(CASE WHEN p.state = 'review' THEN 1 END) AS review
FROM questions q
LEFT JOIN memorization_progress p ON p.question_id = q.question_id
WHERE q.subject_id = ?
`

type SubjectOverviewRow struct {
	Total    int64 `json:"total"`
	Mastered int64 `json:"mastered"`
	Review   int64 `json:"review"`
}

func (q *Queries) SubjectOverview(ctx context.Context, subjectID int64) (SubjectOverviewRow, error) {
	row := q.db.QueryRowContext(ctx, subjectOverview, subjectID)
	var i SubjectOverviewRow
	err := row.Scan(&i.Total, &i.Mastered, &i.Review)
	return i, err
}

